function UIFishPoolStoreBackPackPopupDialog:FillFishingPropsInfo(isNotRefreshSelect, lastEquipId)
    local t = FishingUtils.GetFishingPropsList(self._curFishPlaceId)
    local count = 1
    for k, v in pairs(t) do
        local type = GoodsUtils.GetIdType(v)
        local go = self.OptipnIconGroup.transform:Find("IconNode"..count)
        if not go then
            go = CfUtils.InstantiateGo(self.IconNode, self.OptipnIconGroup)
            go.name = "IconNode"..count
        end
        self:FillFishingProps(go, v, count)

        --跟换装备
        if checkNumber(lastEquipId) > 0 then
            if isNotRefreshSelect then
                local typeLast = GoodsUtils.GetIdType(lastEquipId)
                if typeLast == type then
                    --CfUtils.PlayAnimator(go.transform:Find("AimRoot"), "Idle")
                end
            end
        end

        count = count + 1
    end
    if isNotRefreshSelect then
    else
        self:RefreshSelectType(self._curSelectType)
    end
end

