                str = "<color=#FF4040>"..str.."</color>"
            end
            num = str.."/"..vo.durability
        elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
            local str = checkNumber(dojo.num)
            if checkNumber(dojo.num) <= 0 then
                str = "<color=#FF4040>"..str.."</color>"
            end
            num = "x"..str
        end
    else
        num = "x<color=#FF4040>0</color>"
    end

    --if FishingUtils.IsBaseProps(id) then
    --    num = nil
    --end
    local isBase = FishingUtils.IsBaseProps(id) 
    KTool.SetActive(go.transform:Find("AimRoot/ImgUnlimited"), false)--isBase)
    --[[
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
    if vo then
        CfUtils.FillText(go.transform:Find("TextNumber"), num)
        CfUtils.FillImage(go.transform:Find("ImgIcon"), vo.photoPath)
        CfUtils.SetUISwitchImage(go.transform:Find("ImgRareRing"), checkNumber(vo.ImgRareRing))
    end
    ]]
    --SetButtonAction(go, function()
    --    self:RefreshSelectType(type)
    --end)
    local goodNode = go.transform:Find("AimRoot/GoodNode")
    ---@type GoodNodeMB
    local env = CfUtils.GetLuaScr(goodNode, 'Game.Behaviours.GoodNodeMB')
    if env then
        --KTool.SetActive(env.LvBg.gameObject, true)
    end
    CfUtils.RefeshGoodGo(goodNode, id, num, 0.65, nil, function()
        self:RefreshSelectType(type)
    end)

    if checkNumber(self:GetCurSelectGoodsIndByType(type)) == 0 then
        self:SetCurSelectGoodsIndByType(type, 0)
    end
    KTool.SetActive(go, true)
end

function UIFishPoolStoreBackPackPopupDialog:GetTypeInd(type)
    type = checkNumber(type)
    if type == Constants.IDType.GoodsReel then
        return 2
    elseif type == Constants.IDType.GoodsFishingRod then
        return 1
    elseif type == Constants.IDType.GoodsBait then
        return 4
