--刷新选择类型
function UIFishPoolStoreBackPackPopupDialog:RefreshSelectType(type)
    local ind = self:GetTypeInd(self._curSelectType)
    local go
    if self._curSelectType > 0 then
        go = self.OptipnIconGroup.transform:Find("IconNode"..ind)
        if go then
            KTool.SetActive(go.transform:Find("AimRoot/ImgSelect"), false)
            CfUtils.PlayAnimator(go.transform:Find("AimRoot"), "Idle")
        end
    end
    self._curSelectType = checkNumber(type)
    ind = self:GetTypeInd(self._curSelectType)
    go = self.OptipnIconGroup.transform:Find("IconNode"..ind)
    if go then
        KTool.SetActive(go.transform:Find("AimRoot/ImgSelect"), true)
        CfUtils.PlayAnimator(go.transform:Find("AimRoot"), "Select")
    end

    self:RefreshGoods()
    self:RefreshCurTypeEquipInfo()

    KTool.SetActive(self.StatusContent, false)
    KTool.SetActive(self.StatusLock, false)

    local isNone = checkNumber(self:GetCurSelectGoodsIndByType(self._curSelectType)) == 0
    if not isNone then
        local vo = self._allGoods[self:GetCurSelectGoodsIndByType(self._curSelectType)]
        if vo then
            self:RefreshCurSelectGoodsInfo(vo.id)
        else
            self:RefreshCurSelectGoodsInfo(0)
        end
    end


    CfUtils.SetActive(self.CommonFilterNode.parent.transform:Find("CommonFilterNode2"), self._curSelectType ~= Constants.IDType.GoodsBait)
    --KTool.SetActive(self.StatusEmpty, isNone)
    --KTool.SetActive(self.StatusContent, not isNone)
end

--绘制当前装备的道具
function UIFishPoolStoreBackPackPopupDialog:RefreshCurTypeEquipInfo()
    local equipPropsId = FishingUtils.GetFishingEquipIdByType(self._curSelectType, self._curFishPlaceId)
    if not equipPropsId then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CurrentEquipment, UIFishPoolStoreBackPackGoodsInfoNode)
    if scr then
        scr:Refresh(equipPropsId, true, nil, self._curFishPlaceId)
    end
end

--绘制当前选择的物品
function UIFishPoolStoreBackPackPopupDialog:RefreshCurSelectGoodsInfo(goodsId)
    if checkNumber(goodsId) == 0 then 
        KTool.SetActive(self.SelectEquipment.transform:Find("StatusEmpty"), true)
        KTool.SetActive(self.SelectEquipment.transform:Find("StatusContent"), false)
        KTool.SetActive(self.SelectEquipment.transform:Find("StatusLock"), false)
        return 
    end
    local equipPropsId = FishingUtils.GetFishingEquipIdByType(self._curSelectType, self._curFishPlaceId)
    local isShow = checkNumber(goodsId) ~= checkNumber(equipPropsId)
    KTool.SetActive(self.SelectEquipment.transform:Find("StatusEmpty"), not isShow)
    KTool.SetActive(self.SelectEquipment.transform:Find("StatusContent"), isShow)
    if not isShow then
        return
    end

    local scr = CfUtils.GetLuaScr(self.SelectEquipment, UIFishPoolStoreBackPackGoodsInfoNode)
    if scr then
        scr:Refresh(goodsId, false, function(lastEquipId)
            self:ChooseGoods(self:GetCurSelectGoodsIndByType(self._curSelectType))
            self:RefreshCurTypeEquipInfo()
            self:FillFishingPropsInfo(true, lastEquipId)

            for k, v in pairs(self._allGoods) do
                if checkNumber(v.id) == checkNumber(lastEquipId) then
                    local go = self.LoopList:GetShownItemByItemIndex(k - 1)
                    if go then
                        local lastScr = CfUtils.GetLuaScr(go, UIFishPoolStoreBackPackGoodsNode)
                        if lastScr then
                            lastScr:RefreshSelectActive(false)
                        end
                    end
                end
            end
        end, self._curFishPlaceId)
    end
end

--列表
function UIFishPoolStoreBackPackPopupDialog:RefreshGoods()
    self._allGoods = self:GetAllGoodsData()
    if self._isInitList then
        self.LoopList:SetListItemCount(table.count(self._allGoods))
    else
        self.LoopList:InitListView(0, Bind(self, self.OnRefreshIndex))
        self.LoopList:SetListItemCount(table.count(self._allGoods))
        self._isInitList = true
    end
end

function UIFishPoolStoreBackPackPopupDialog:OnRefreshIndex(go, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = go
    local vo = self._allGoods[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolStoreBackPackGoodsNode)
    if scr then
        scr:Refresh(vo, function()
            if checkNumber(FishingUtils.GetFishingEquipIdByType(self._curSelectType, self._curFishPlaceId)) == checkNumber(vo.id) then
                GameUtils.Toast(localize("已装备"))
                return
            end

            self:ChooseGoods(index + 1)
        end, self._curFishPlaceId)

        if (index + 1) == checkNumber(self:GetCurSelectGoodsIndByType(self._curSelectType)) then
            scr:RefreshSelectActive(true)
            self:ChooseGoods(index + 1)
        end
    end
    return cell
end

--选择物品
function UIFishPoolStoreBackPackPopupDialog:ChooseGoods(ind)
    ind = checkNumber(ind)
    local t = self:GetAllGoodsData()
    if not t then
        return
    end
    local go
    local lastSelectInd = self:GetCurSelectGoodsIndByType(self._curSelectType)
    if checkNumber(lastSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFishPoolStoreBackPackGoodsNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end

    self:SetCurSelectGoodsIndByType(self._curSelectType, ind)
    local curSelectInd = self:GetCurSelectGoodsIndByType(self._curSelectType)
    if checkNumber(curSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFishPoolStoreBackPackGoodsNode)
            if curScr then
                curScr:RefreshSelectActive(true)
            end
        end
    end
    local vo = self._allGoods[self:GetCurSelectGoodsIndByType(self._curSelectType)]
    if vo then
        self:RefreshCurSelectGoodsInfo(vo.id)
    else
        self:RefreshCurSelectGoodsInfo(0)
    end
    --KTool.SetActive(self.StatusContent, true)
    --KTool.SetActive(self.StatusEmpty, false)
end

--设置页签的选择下标
function UIFishPoolStoreBackPackPopupDialog:SetCurSelectGoodsIndByType(type, ind)
    ind = checkNumber(ind)
    if checkNumber(type) == 0 or ind == 0 then
        return
    end
    self._selectGoodsInds[checkString(type)] = ind
end

function UIFishPoolStoreBackPackPopupDialog:GetCurSelectGoodsIndByType(type)
    if checkNumber(type) == 0 then
        return 0
    end
    return self._selectGoodsInds[checkString(type)]
end

--获取当前页签展示的数据
function UIFishPoolStoreBackPackPopupDialog:GetAllGoodsData()
    if not self._bufferData[self._curSelectType] then
        local t = {}
        if self._curSelectType == Constants.IDType.GoodsFishingRod then
            t = FishingUtils.GetAllFishingRodVo(self._curFishPlaceId)
        elseif self._curSelectType == Constants.IDType.GoodsReel then
            t = FishingUtils.GetAllFishingReelVo(self._curFishPlaceId)
        elseif self._curSelectType == Constants.IDType.GoodsBait then
            t = FishingUtils.GetAllFishingBaitVo(self._curFishPlaceId)
        elseif self._curSelectType == Constants.IDType.GoodsFishingLine then
            t = FishingUtils.GetAllFishingLineVo(self._curFishPlaceId)
        end 
        local _t = {}
        for k, v in pairs(t) do
            --拥有或者可购买
            if FishingUtils.IsHaveFishingGoodsDojo(v.id) or checkNumber(v.isStoreGood) == 1 then
                table.insert(_t, v)
            end
        end
        self._bufferData[self._curSelectType] = _t
    end

    local equipVo = nil
    --留空占位
    local returnT = {}
    for k, v in pairs(self._bufferData[self._curSelectType]) do
        local isCanUse 
        if checkNumber(self._curPlaceData.id) == 0 then
            isCanUse = true
        else
            isCanUse = FishingUtils.IsCanUseInPlace(v.id, self._curPlaceData.id)
        end
        
        if checkNumber(FishingUtils.GetFishingEquipIdByType(self._curSelectType, self._curFishPlaceId)) == checkNumber(v.id) then
            equipVo = v
        elseif isCanUse then
            table.insert(returnT, v)
        end
    end

    local t1 = {}
    local t2 = {}
    for k, v in pairs(returnT) do
        --拥有或者可购买
        if checkNumber(v.isStoreGood) == 1 then
            table.insert(t1, v)
        else
            table.insert(t2, v)
        end
    end

    table.sort(t1, function(a, b)
        local vo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.id)
        local vo2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.id)
        if not self._curSortRareData then
            return checkNumber(vo1.id) < checkNumber(vo2.id)
        else
            if self._curSortRareData.id == 1 then
                if checkNumber(vo1.quality) == checkNumber(vo2.quality) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.quality) < checkNumber(vo2.quality)
                end
            elseif self._curSortRareData.id == 2 then
                if checkNumber(vo1.quality) == checkNumber(vo2.quality) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.quality) > checkNumber(vo2.quality)
                end
            elseif self._curSortRareData.id == 3 then
                vo1 = FishingUtils.GetFishingGoodsVoById(a.id)
                vo2 = FishingUtils.GetFishingGoodsVoById(b.id)
                if checkNumber(vo1.needLevel) == checkNumber(vo2.needLevel) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.needLevel) < checkNumber(vo2.needLevel)
                end
            elseif self._curSortRareData.id == 4 then
                vo1 = FishingUtils.GetFishingGoodsVoById(a.id)
                vo2 = FishingUtils.GetFishingGoodsVoById(b.id)
                if checkNumber(vo1.needLevel) == checkNumber(vo2.needLevel) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.needLevel) > checkNumber(vo2.needLevel)
                end
            end
            return false
        end
    end)

    table.sort(t2, function(a, b)
        local vo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.id)
        local vo2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.id)
        if not self._curSortRareData then
            return checkNumber(vo1.id) < checkNumber(vo2.id)
        else
            if self._curSortRareData.id == 1 then
                if checkNumber(vo1.quality) == checkNumber(vo2.quality) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.quality) < checkNumber(vo2.quality)
                end
            elseif self._curSortRareData.id == 2 then
                if checkNumber(vo1.quality) == checkNumber(vo2.quality) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.quality) > checkNumber(vo2.quality)
                end
            elseif self._curSortRareData.id == 3 then
                vo1 = FishingUtils.GetFishingGoodsVoById(a.id)
                vo2 = FishingUtils.GetFishingGoodsVoById(b.id)
                if checkNumber(vo1.needLevel) == checkNumber(vo2.needLevel) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.needLevel) < checkNumber(vo2.needLevel)
                end
            elseif self._curSortRareData.id == 4 then
                vo1 = FishingUtils.GetFishingGoodsVoById(a.id)
                vo2 = FishingUtils.GetFishingGoodsVoById(b.id)
                if checkNumber(vo1.needLevel) == checkNumber(vo2.needLevel) then
                    return checkNumber(vo1.id) < checkNumber(vo2.id)
                else
                    return checkNumber(vo1.needLevel) > checkNumber(vo2.needLevel)
                end
            end
            return false
        end
    end)
    
    returnT = {}
    for k, v in pairs(t1) do
        table.insert(returnT, v)
    end
    for k, v in pairs(t2) do
        table.insert(returnT, v)
    end

    --[[
    table.sort(returnT, function(a, b)
        local vo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.id)
        local vo2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.id)
        if not self._curSortRareData then
            return checkNumber(vo1.id) < checkNumber(vo2.id)
        else
            if self._curSortRareData.id == 1 then
                return checkNumber(vo1.quality) < checkNumber(vo2.quality)
            else
                return checkNumber(vo1.quality) > checkNumber(vo2.quality)
            end
        end
    end)
    ]]

    if equipVo then 
        table.insert(returnT, 1, equipVo)
    end
    return returnT
end

--刷新界面
function UIFishPoolStoreBackPackPopupDialog:OnFishGoodsChange()
    if self._isInitList then
        self.LoopList:SetListItemCount(table.count(self._allGoods))
    else
        self.LoopList:InitListView(0, Bind(self, self.OnRefreshIndex))
        self.LoopList:SetListItemCount(table.count(self._allGoods))
        self._isInitList = true
    end
    self:FillFishingPropsInfo(true)
    self:RefreshCurTypeEquipInfo(true)
end

function UIFishPoolStoreBackPackPopupDialog:OnBtnClose()
    UIModule.BackDialog()
end

function UIFishPoolStoreBackPackPopupDialog:Update()
    if Utils.TouchCount() > 0 then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            if self._isShowRareSortType then
                local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.DropDown, position,
                UIModule.RootCanvas.canvas.worldCamera)
                if not isInRect then
                    ---不在区域中
                    self:OnBtnRefreshBtnAlign()
                end
            end

            if self._isShowPlaceSortType then
                local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.DropDown2, position,
                UIModule.RootCanvas.canvas.worldCamera)
                if not isInRect then
                    ---不在区域中
                    self:OnBtnRefreshBtnAlign2()
                end
            end
        end
    end
end

function UIFishPoolStoreBackPackPopupDialog:OnFocus(focus)
    if focus then
        CfUtils.RefreshTopGoods({
            Constants.Currency.FreeDiamondId,
            Constants.Currency.GoldId,
            Constants.Currency.FishConsume
        })
    end
end

function UIFishPoolStoreBackPackPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.RefreshTopGoods({
            Constants.Currency.FreeDiamondId,
            Constants.Currency.GoldId,
            Constants.Currency.FishConsume
        })

        local BehaviourAction = CS.Engine.Lib.BehaviourAction
        local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        if behaviourAction then
            behaviourAction.UpdateAction = Bind(self, self.Update)
            self._behaviourAction = behaviourAction
        end
    end))
    return coWait
end

function UIFishPoolStoreBackPackPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end

        Events.RemoveListener(Constants.EventNames.FishGoodsChange, self.EventFishGoodsChange)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIFishPoolStoreBackPackPopupDialog:OnCaptureAction()
    local effectBg = KTool.GetOrAddComponent(self.controller.gameObject, typeof(CS.UGUI.Effects.UIEffectCapturedImage))
    if effectBg then
        effectBg:Capture()
    end
end

function UIFishPoolStoreBackPackPopupDialog:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.ResetNavigatorCustomBackAction()
        cs_coroutine.yield_return(self:OnCaptureAction())
    end))
    return coWait
end

return UIFishPoolStoreBackPackPopupDialog
